// 命令接口
interface Command { void execute(); void undo(); }

// 接收者
class Light { void on() { System.out.println("on"); } void off() { System.out.println("off"); } }

// 具体命令
class LightOnCommand implements Command {
    private final Light light;
    LightOnCommand(Light light) { this.light = light; }
    public void execute() { light.on(); }
    public void undo() { light.off(); }
}

// 调用者(可记录历史以撤销)
class Remote {
    private final java.util.Deque<Command> history = new java.util.ArrayDeque<>();
    void submit(Command c) { c.execute(); history.push(c); }
    void undoLast() { if (!history.isEmpty()) history.pop().undo(); }
}
